const agora = new Date();
return $input.all().map(({ json: item }) => {
  const prazo = new Date(item.prazo_proposta);
  const diffHoras = Math.round((prazo - agora) / (1000 * 60 * 60));
  const diffDias = Math.floor(diffHoras / 24);
  const horasRestantes = diffHoras % 24;
  let tempoTexto;
  if (diffDias >= 1) {
    tempoTexto = diffDias + ' dia(s)' + (horasRestantes > 0 ? ' e ' + horasRestantes + 'h' : '');
  } else if (diffHoras > 0) {
    tempoTexto = diffHoras + ' hora(s)';
  } else {
    tempoTexto = 'menos de 1 hora';
  }
  const texto = '⏰ Faltam ' + tempoTexto + ' para o prazo da licitacao "' + (item.objeto_resumo || item.pncp_id) + '". Ainda nao ha proposta enviada registrada -- corre!';
  return { json: { numero: (item.whatsapp_numero || '').replace(/\D/g, ''), texto } };
});
